select orca_write_record(
  'aaaaaaaa-0000-0000-0000-00000000000a', 'functional'::record_domain, 'Cannot face the commute. Missed two days. Everything is loud and I am not managing conversations at work. Sleeping badly. I do not want to write these entries at the moment.',
