  '2026-05-16T09:00:00Z'::timestamptz, 'Worst week so far', 'e0000000-0000-0000-0000-000000000001',
  'high'::sensitivity_level, 'subject_confirmed'::validation_status, 0.75, null, null, 'f0000000-0000-0000-0000-000000000032');
select orca_write_record(
  'aaaaaaaa-0000-0000-0000-00000000000a', 'clinical'::record_domain, 'Reviewed in context of current presentation. Assessment favours autistic burnout over anxiety relapse; medication increase not indicated. Sertraline continued at existing dose. Recommendation is load reduction, not pharmacological change.',
