select orca_write_record(
  'aaaaaaaa-0000-0000-0000-00000000000a', 'support'::record_domain, 'Tried noise-cancelling headphones for the whole commute for a fortnight. Stopping. Taking the sound away made it harder to judge where people were. Nearly went down the stairs twice.',
